// Deduplicacion: usar staticData para evitar procesar mismo mensaje dos veces
const body = $input.first().json.body || {};
try {
  if (body.object !== 'whatsapp_business_account') { return []; }
  const ch = (((body.entry || [])[0] || {}).changes || [])[0] || {};
  const value = ch.value || {};
  const msg = (value.messages || [])[0];
  if (!msg) {
    // Acuses de entrega: registrar los FALLIDOS para verlos en Chats IA (los demas se ignoran)
    const st = (value.statuses || [])[0];
    if (st && st.status === 'failed') {
      const err = ((st.errors || [])[0] || {});
      return [{ json: { es_fallo_entrega: true, from: st.recipient_id || '', fallo_detalle: 'ENTREGA FALLIDA (' + (err.code || '?') + ' ' + (err.title || '') + '): el mensaje del bot NO le llego al cliente.' } }];
    }
    return [];
  }

  // Ignorar mensajes viejos (reintentos de Meta tras caida del webhook): >15 min
  const ts = Number(msg.timestamp || 0);
  if (ts && (Date.now() / 1000 - ts) > 900) { return []; }

  // Deduplicacion por message_id
  const msgId = msg.id;
  const processed = $getWorkflowStaticData('global');
  if (!processed.msgs) processed.msgs = {};
  if (processed.msgs[msgId]) { return []; } // Ya procesado
  processed.msgs[msgId] = Date.now();
  // Limpiar mensajes viejos (>5 min)
  const now = Date.now();
  for (const id of Object.keys(processed.msgs)) {
    if (now - processed.msgs[id] > 300000) delete processed.msgs[id];
  }

  const contact = (value.contacts || [])[0] || {};
  // Meta puede mandar usuarios por "username": el remitente llega en from_user_id / contacts[0].user_id (formato CO.xxxx), no en from
  const remitente = msg.from || msg.from_user_id || contact.wa_id || contact.user_id || '';
  if (!remitente) { return []; } // sin remitente no hay a quien responder
  const t = msg.type;
  let texto = '', es_audio = false, audio_id = '';
  // Modo test: ids 'wamid.TEST_' desde numeros ficticios NO se envian a Meta (se registra todo en BD igual)
  const es_test = String(msg.id || '').startsWith('wamid.TEST_') && String(remitente) !== '573172625415';
  let es_imagen = false, imagen_id = '', caption = '', imagen_url_test = '';
  if (t === 'text') { texto = (msg.text || {}).body || ''; }
  else if (t === 'audio') { es_audio = true; audio_id = (msg.audio || {}).id || ''; }
  else if (t === 'image') {
    // v12: foto del cliente -> se descarga de Meta y se analiza con vision antes de pasar al agente
    es_imagen = true; imagen_id = (msg.image || {}).id || ''; caption = String((msg.image || {}).caption || '').trim();
    if (es_test) { // solo pruebas: URL publica en vez de Meta, y SOLO de Wikimedia por https (el webhook es publico: nada de URLs arbitrarias)
      const lk = String((msg.image || {}).link || '');
      if (/^https:\/\/(upload|thumb|commons)\.wikimedia\.org\/[^\s]*$/.test(lk)) imagen_url_test = lk; // regex: el sandbox de n8n no trae URL()
      if (!imagen_url_test) { es_imagen = false; imagen_id = ''; caption = '(foto enviada por el cliente que no se pudo analizar)' + (caption ? ' ' + caption : ''); }
    }
    texto = caption;
  }
  else { texto = '[Mensaje tipo ' + t + '. Pidele que escriba, envie audio o una foto.]'; }
  return [{ json: { from: remitente, nombre: (contact.profile || {}).name || (contact.profile || {}).username || '', tipo: t, message_id: msg.id, es_audio, audio_id, es_imagen, imagen_id, caption, imagen_url_test, texto, es_test } }];
} catch (e) { return []; }

const orig = $('Extraer mensaje').item.json;
let transcripcion = '';
try { transcripcion = $input.first().json.text || ''; } catch (e) {}
let texto = (transcripcion || orig.texto || '').trim();
// 2026-09-27 v11: Whisper devuelve frases inventadas cuando el audio esta vacio o con ruido (caso real: "Subtitulos realizados por la comunidad de Amara.org")
const ALUCINACION = /amara\.org|subt[ií]tulos? (realizados|por|hechos)|gracias por ver|suscr[ií]b(e|a)te|www\.|traducido por|^\W*$/i;
let audio_no_entendido = false;
if (orig.es_audio && (!texto || ALUCINACION.test(texto))) { texto = '(nota de voz que no se entendio: pidale que la repita o que escriba)'; audio_no_entendido = true; }
// v12: foto del cliente -> lo que vio el modelo de vision entra como texto marcado
let foto_no_analizada = false;
if (orig.es_imagen) {
  let d = '';
  try { d = String((($input.first().json.choices || [])[0] || {}).message?.content || '').trim(); } catch (e) {}
  if (d) { texto = '(foto enviada por el cliente. Lo que se ve en la foto: ' + d + ')'; }
  else { texto = '(foto enviada por el cliente que no se pudo analizar: pidale que la mande de nuevo mas cerca y con luz, o que le cuente que ve)'; foto_no_analizada = true; }
  if (orig.caption) texto += ' El cliente escribio junto a la foto: "' + orig.caption + '"';
}
return [{ json: { ...orig, texto, fue_audio: !!orig.es_audio, audio_no_entendido, fue_imagen: !!orig.es_imagen, foto_no_analizada } }];

const inp = $input.first().json || {};
let raw = inp.output || inp.text || '';
if (typeof raw !== 'string') raw = String(raw || '');
let fallback = false;
if (!raw.trim()) {
  raw = 'Disculpe, se me fue la señal un momento. ¿Me repite por favor lo último que me escribió?';
  fallback = true;
}
const from = $('Extraer mensaje').item.json.from;

const mediaMap = {
  '[ENVIAR_IMAGEN]': 'imagen',
  '[ENVIAR_VIDEO_PEPINO]': 'video_pepino',
  '[ENVIAR_VIDEO_PAPAYA]': 'video_papaya',
  '[ENVIAR_VIDEO_SANDIA]': 'video_sandia'
};
let media = null;
for (const [tag, tipo] of Object.entries(mediaMap)) {
  if (raw.includes(tag)) { media = tipo; break; }
}

// v14: ficha tecnica en PDF y redes sociales al cierre
const ficha = raw.includes('[ENVIAR_FICHA]');
const redes = raw.includes('[ENVIAR_REDES]');

// Datos del lead
const datos = {};
const datoRe = /\[DATO_(NOMBRE|CIUDAD|DEPTO|CULTIVO):([^\]]*)\]/g;
let m;
while ((m = datoRe.exec(raw)) !== null) { datos[m[1].toLowerCase()] = m[2].trim(); }

// Pedido cerrado por el agente
let pedido = null;
const pIni = raw.indexOf('[CREAR_PEDIDO:');
if (pIni !== -1) {
  const pFin = raw.indexOf(']', pIni);
  if (pFin !== -1) {
    try { pedido = JSON.parse(raw.substring(pIni + 14, pFin)); }
    catch (e) { pedido = { parse_error: true, raw: raw.substring(pIni + 14, pFin) }; }
  }
}

// Interes en ser distribuidor (v11)
let interes = null;
const iIni = raw.indexOf('[INTERES_DISTRIBUIDOR:');
if (iIni !== -1) {
  const iFin = raw.indexOf(']', iIni);
  if (iFin !== -1) {
    try { interes = JSON.parse(raw.substring(iIni + 22, iFin)); }
    catch (e) { interes = { parse_error: true, raw: raw.substring(iIni + 22, iFin) }; }
  }
}

// Limpiar TODOS los tags del texto que ve el cliente
let respuesta = raw
  .replace(/\[ENVIAR_[A-Z_]+\]/g, '')
  .replace(/\[DATO_[A-Z]+:[^\]]*\]/g, '')
  .replace(/\[CREAR_PEDIDO:[^\]]*\]/g, '')
  .replace(/\[INTERES_DISTRIBUIDOR:[^\]]*\]/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return [{ json: { from, respuesta, media, datos, tiene_datos: Object.keys(datos).length > 0, pedido, tiene_pedido: !!pedido, interes, tiene_interes: !!interes, fallback, ficha, redes } }];

// Pausa anti-rafaga (5 s) sin nodo Wait ni staticData
await new Promise(r => setTimeout(r, 5000));
return $input.all();

// 2026-09-24 · Precios VIVOS de la BD (Panel › Inventario). El CEO cambia un precio y el agente lo usa en el siguiente mensaje.
// Si la consulta falla, quedan los precios de respaldo (los de la landing al 2026-09-24).
const RESPALDO = { 1: 129900, 4: 409900, 10: 1100000, 20: 1998000 };
const P = {};
const M = {}; // precio mayorista fijado por el CEO (NULL = no fijado)
for (const it of $input.all()) {
  const p = it.json || {};
  if (Number(p.litros) > 0 && Number(p.precio_venta) > 0) P[Number(p.litros)] = Number(p.precio_venta);
  if (Number(p.litros) > 0 && Number(p.precio_mayorista) > 0 && Number(p.precio_mayorista) < Number(p.precio_venta)) M[Number(p.litros)] = Number(p.precio_mayorista);
}
const fuente = Object.keys(P).length ? 'bd' : 'respaldo';
if (fuente === 'respaldo') Object.assign(P, RESPALDO);
const $$ = (n) => '$' + String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const L = Object.keys(P).map(Number).sort((a, b) => a - b);
const P1 = P[1] || null;
const porLitro = (l) => P[l] / l;
const NOMBRE = {
  1: '1 litro (envase de 1 L)',
  4: 'Galón de 4 litros (UN solo envase de 4 L)',
  10: '10 unidades (10 envases de 1 L = 10 litros)',
  20: '20 unidades (20 envases de 1 L = 20 litros)'
};
const CORTO = { 1: 'el litro', 4: 'el galón', 10: '10 unidades', 20: '20 unidades' };
const nombre = (l) => NOMBRE[l] || (l + ' litros');
const corto = (l) => CORTO[l] || (l + ' litros');
const mejor = L.reduce((a, b) => (porLitro(b) < porLitro(a) ? b : a), L[0]);

// Combinación más barata para N litros (misma lógica que el agente promete al cliente)
function combo(n) {
  const best = [0], pick = [0];
  for (let i = 1; i <= n; i++) {
    best[i] = Infinity;
    for (const l of L) if (l <= i && best[i - l] + P[l] < best[i]) { best[i] = best[i - l] + P[l]; pick[i] = l; }
  }
  const partes = {}; let i = n;
  while (i > 0 && pick[i]) { partes[pick[i]] = (partes[pick[i]] || 0) + 1; i -= pick[i]; }
  const txt = Object.keys(partes).map(Number).sort((a, b) => b - a)
    .map(l => (partes[l] > 1 ? partes[l] + ' ' : '') + (l === 1 ? (partes[l] > 1 ? 'envases de 1 L' : '1 litro') : l === 4 ? (partes[l] > 1 ? 'galones' : 'galón') : corto(l))).join(' + ');
  return { total: best[n], txt };
}

const lineas = L.map(l => {
  let s = '- ' + nombre(l) + ': ' + $$(P[l]);
  if (l > 1) s += ', es decir ' + $$(porLitro(l)) + ' el litro';
  if (l === mejor && L.length > 1) s += ', el mejor precio por litro';
  if (l > 1 && P1 && l * P1 - P[l] > 0) s += '. Ahorra ' + $$(l * P1 - P[l]) + ' frente a ' + l + ' litros sueltos';
  if (l === 4) s += '. Es el más vendido';
  s += '. Alcanza para ' + l + (l === 1 ? ' tanque' : ' tanques') + ' de 200 litros de agua (' + $$(l * 200).slice(1) + ' litros de mezcla).';
  return s;
});
const ej = P[4] ? 'El galón de 4 litros vale ' + $$(P[4]) + ', le sale a ' + $$(porLitro(4)) + ' el litro' + (P1 && 4 * P1 > P[4] ? ' y ahorra ' + $$(4 * P1 - P[4]) + ' frente a comprar los litros sueltos' : '') : '';
const bloque = lineas.join('\n') + '\n- Cuando des un precio, di siempre las tres cosas: el total, cuánto sale el litro y cuánto ahorra.' + (ej ? ' Ejemplo: "' + ej + '".' : '');

const combos = [2, 3, 5, 8, 12].map(n => {
  const c = combo(n);
  let s = n + ' litros = ' + c.txt + ' = ' + $$(c.total);
  if (n === 3 && P[4] && P[4] < c.total * 1.15) s += ', mejor ofrézcale el galón por ' + $$(P[4]) + ' que trae 4';
  return s;
}).join('; ');
const combinaciones = 'OTRAS CANTIDADES: se arman combinando presentaciones y el total es la SUMA exacta (' + combos + '). Nunca inventes otro precio, promoción ni descuento.';

const bomba = '- Rendimiento en plata por bomba de 20 L (100 ml de producto): ' + L.map(l => 'con ' + corto(l) + ' ' + $$(porLitro(l) / 10)).join('; ') + '.';
const objecion = 'desde ' + $$(porLitro(mejor) / 10) + ' con ' + corto(mejor) + (P[4] && mejor !== 4 ? ', ' + $$(porLitro(4) / 10) + ' con el galón' : '');
const cierre = (P1 && P[4]) ? '"¿Le despacho el litro a ' + $$(P1) + ' o aprovecha el galón de 4 litros a ' + $$(P[4]) + ', que le sale a ' + $$(porLitro(4)) + ' el litro?"' : '';

// 2026-09-27 v11: precio mayorista para quien quiere ser distribuidor (solo lo fijado en Inventario; lo demas lo confirma el equipo)
const LM = Object.keys(M).map(Number).sort((a, b) => a - b);
const sinM = L.filter(l => !M[l]);
let distribuidor;
if (LM.length) {
  distribuidor = 'PRECIO MAYORISTA vigente: ' + LM.map(l => corto(l) + ' le queda al distribuidor en ' + $$(M[l]) + ' y lo vende al publico en ' + $$(P[l]) + ' (gana ' + $$(P[l] - M[l]) + (l > 1 ? ' por ' + corto(l) : ' por litro') + ')').join('; ') + '.'
    + (sinM.length ? ' El precio mayorista ' + sinM.map(l => corto(l).replace(/^el /, 'del ')).join(', ') + ' se lo confirma el equipo de OZOAGRO.' : '');
} else {
  distribuidor = 'El precio mayorista exacto se lo confirma el equipo de OZOAGRO cuando lo llamen (no des cifras).';
}
return [{ json: { fuente, precios: P, mayorista: M, bloque, combinaciones, bomba, objecion, cierre, distribuidor }, pairedItem: { item: 0 } }];

// Fusiona el interes de ser distribuidor en wa_conversaciones.metadata (sin migracion de BD)
const p = $('Parsear respuesta').item.json;
const rows = $input.all().map(i => i.json).filter(j => j && j.id);
const prev = (rows[0] && rows[0].metadata && typeof rows[0].metadata === 'object') ? rows[0].metadata : {};
const ant = prev.interes_distribuidor || {};
const nuevo = Object.assign({}, ant);
const src = (p.interes && !p.interes.parse_error) ? p.interes : {};
for (const [k, v] of Object.entries(src)) { if (v !== null && v !== undefined && String(v).trim() !== '') nuevo[k] = String(v).trim(); }
if (p.interes && p.interes.parse_error) nuevo.raw = p.interes.raw;
nuevo.telefono = nuevo.telefono || p.from;
nuevo.primera_vez = ant.primera_vez || new Date().toISOString();
nuevo.actualizado = new Date().toISOString();
nuevo.veces = (Number(ant.veces) || 0) + 1;
nuevo.estado = ant.estado || 'nuevo';
nuevo.origen = 'agente_andres';
return [{ json: { from: p.from, existe: rows.length > 0, metadata: Object.assign({}, prev, { interes_distribuidor: nuevo }) } }];

// Binario -> base64 para mandarlo a OpenAI (la URL de Meta exige token, OpenAI no la puede leer)
const item = $input.first();
const bin = (item.binary && item.binary.data) || {};
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
return [{ json: { b64: buf.toString('base64'), mime: bin.mimeType || 'image/jpeg', bytes: buf.length } }];

// v14 (2026-10-12): mensajes extra despues de la respuesta, EN ORDEN: foto/video del producto, ficha tecnica PDF, redes.
// Candados deterministas (no dependen solo del prompt):
//  - ficha: solo si el agente la OFRECIO en su mensaje anterior o el cliente la PIDIO en lo que acaba de escribir.
//  - redes: una sola vez por conversacion (metadata.redes_enviadas); salen con [ENVIAR_REDES] o con un pedido bien formado.
//  - si no se pudo leer la conversacion: NO salen ficha ni redes (fallar cerrado: sin estado no hay candado ni marca segura).
// Cada item lleva la 'marca' que se guarda en metadata SOLO si el envio sale bien ('Confirmar envios' + 'Unir marcas').
const p = $('Parsear respuesta').item.json;
const ex = $('Extraer mensaje').item.json;
const conv = ($input.all().map(i => i.json).find(j => j && j.id)) || null;
const msgs = (conv && Array.isArray(conv.wa_mensajes)) ? conv.wa_mensajes : []; // mas reciente primero
const BASE = 'https://ozoagro.co/media/';
const FICHA_URL = 'https://virtanancucuta.github.io/ozoagro/landing/media/ficha_tecnica_ozoagro.pdf';
const REDES = "Nos puede seguir en nuestras redes para que nos conozca más y vea nuestro trabajo a fondo 🌱\n\nPágina web\nhttps://ozoagrolatam.com\n\nFacebook\nhttps://www.facebook.com/latamozoagro\n\nInstagram\nhttps://www.instagram.com/ozoagro\n\nTikTok\nhttps://www.tiktok.com/@ozoagrolatam";
const MEDIA = {
  imagen: { type: 'image', url: BASE + 'producto.jpg', registro: '[Foto del producto enviada]' },
  video_pepino: { type: 'video', url: BASE + 'video_pepino.mp4', registro: '[Video de resultados en pepino enviado]' },
  video_papaya: { type: 'video', url: BASE + 'video_papaya.mp4', registro: '[Video de resultados en papaya enviado]' },
  video_sandia: { type: 'video', url: BASE + 'video_sandia.mp4', registro: '[Video de resultados en sandía enviado]' }
};
// filas que registran envios extra ("[Ficha ... enviada]", "[Video ...]", el texto de redes): no son mensajes del agente
const esRegistro = (c) => { const s = String(c || '').trim(); return (s.startsWith('[') && s.endsWith(']')) || s === REDES; };
const out = [];
const item = (tipo, payload, registro, marca) => out.push({ json: { tipo, from: p.from, es_test: !!ex.es_test, payload, registro, marca: marca || null } });

const m = MEDIA[p.media];
if (m) item(p.media, { type: m.type, [m.type]: { link: m.url } }, m.registro);

if (conv) {
  const meta = (conv.metadata && typeof conv.metadata === 'object') ? conv.metadata : {};
  if (p.ficha) {
    // primera fila real del agente = respuesta actual (ya registrada); la anterior = siguiente 'assistant' que no sea registro
    let vistos = 0, previoAgente = '', delCliente = '';
    for (const r of msgs) {
      if (r.rol === 'assistant') { if (esRegistro(r.contenido)) continue; vistos++; if (vistos === 2) { previoAgente = String(r.contenido || ''); break; } }
      else if (r.rol === 'user' && vistos === 1) delCliente += ' ' + String(r.contenido || '');
    }
    if (/ficha/i.test(previoAgente) || /(ficha|pdf)/i.test(delCliente))
      item('ficha', { type: 'document', document: { link: FICHA_URL, filename: 'Ficha técnica OZOAGRO.pdf' } }, '[Ficha técnica OZOAGRO enviada en PDF]', 'ficha_enviada');
  }
  const pedidoOk = !!(p.tiene_pedido && p.pedido && !p.pedido.parse_error);
  if ((p.redes || pedidoOk) && !meta.redes_enviadas)
    item('redes', { type: 'text', text: { body: REDES, preview_url: false } }, REDES, 'redes_enviadas');
}
return out;

// Una sola escritura por ejecucion: metadata leida en 'Leer contexto envios' + marcas de lo enviado con exito.
const marcas = $input.all().map(i => i.json.marca).filter(Boolean);
if (!marcas.length) return [];
const conv = ($('Leer contexto envios').all().map(i => i.json).find(j => j && j.id)) || null;
if (!conv) return [];
const meta = Object.assign({}, (conv.metadata && typeof conv.metadata === 'object') ? conv.metadata : {});
const ahora = new Date().toISOString();
for (const k of marcas) meta[k] = ahora;
return [{ json: { from: $input.first().json.from, metadata: meta } }];
